def _studio_cookie_value(headers, name: str) -> str:
    raw = str(headers.get("Cookie", "") or "")
    jar = SimpleCookie()
    try:
        jar.load(raw)
        return str(jar.get(name).value if jar.get(name) else "").strip()
    except Exception:
        return ""

